"""Browser-native EconAtlas management panel."""

PANEL_HTML = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>EconAtlas · 全球宏观数据平台</title>
<style>
:root{--primary:#5868ef;--soft:#eef1ff;--text:#172033;--muted:#7b879b;--line:#e3e8f1;--bg:#f5f7fb;--good:#16a77a;--warn:#e89b2c;--bad:#d94a5a}*{box-sizing:border-box}body{margin:0;font-family:Inter,"PingFang SC","Microsoft YaHei",sans-serif;background:var(--bg);color:var(--text)}button,input,textarea,select{font:inherit}.top{height:64px;position:fixed;inset:0 0 auto;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 24px;z-index:20}.brand{display:flex;align-items:center;gap:11px;font-weight:900;font-size:21px;color:#0d3a93}.logo{width:40px;height:40px;position:relative;border-radius:50%;border:3px solid #0d3a93;background:linear-gradient(135deg,transparent 47%,#1769ff2e 48% 52%,transparent 53%),radial-gradient(circle at 50% 48%,#fff 0 38%,#dff3ff 39% 100%);box-shadow:0 8px 18px #1769ff29}.logo:after{content:"";position:absolute;left:7px;right:6px;bottom:6px;height:20px;background:linear-gradient(90deg,#0b2f85,#139cff);clip-path:polygon(0 100%,0 58%,16% 58%,16% 100%,25% 100%,25% 42%,41% 42%,41% 100%,50% 100%,50% 24%,66% 24%,66% 100%,76% 100%,76% 0,92% 0,92% 100%)}.logo:before{content:"";position:absolute;left:-5px;right:-2px;bottom:4px;height:17px;border-bottom:3px solid #0b2f85;border-radius:50%;transform:rotate(-24deg)}.top-sub{margin-left:16px;padding-left:16px;border-left:1px solid var(--line);font-size:13px;color:var(--muted)}.top-status{margin-left:auto;display:flex;gap:9px}.pill,.badge{font-size:12px;border:1px solid var(--line);border-radius:20px;padding:7px 11px;color:#657189;background:#fff}.pill i{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--good);margin-right:6px}.badge{display:inline-block;background:#eefaf6;color:var(--good);border:0}.side{position:fixed;top:64px;bottom:0;left:0;width:246px;background:#fff;border-right:1px solid var(--line);padding:18px 13px;overflow:auto}.group{font-size:11px;color:#a0a9b9;margin:18px 13px 7px;letter-spacing:.08em}.menu{width:100%;border:0;background:transparent;text-align:left;padding:11px 13px;border-radius:8px;color:#556176;cursor:pointer;margin:2px 0}.menu:hover{background:#f5f7fc}.menu.active{background:var(--soft);color:var(--primary);font-weight:700}.menu span{display:inline-block;width:25px}.main{margin-left:246px;padding-top:64px;min-height:100vh}.content{max-width:1480px;margin:auto;padding:28px}.page-head{display:flex;align-items:flex-start;margin-bottom:22px}.page-head h1{font-size:25px;margin:0 0 7px}.page-head p{margin:0;color:var(--muted);font-size:14px}.head-action{margin-left:auto}.btn{border:1px solid var(--line);background:#fff;border-radius:8px;padding:9px 14px;cursor:pointer;color:#526077}.btn.primary{background:var(--primary);border-color:var(--primary);color:#fff}.btn:disabled{opacity:.55;cursor:wait}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.card,.panel{background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:0 4px 16px #24345208}.card{padding:18px}.card label{font-size:13px;color:var(--muted)}.card strong{display:block;font-size:26px;margin:10px 0 4px}.card small{color:#98a2b3}.grid2{display:grid;grid-template-columns:1.25fr .75fr;gap:16px;margin-top:16px}.panel{padding:20px}.panel h3{font-size:16px;margin:0 0 15px}.bars,.pipeline{display:grid;gap:11px}.bar-row{display:grid;grid-template-columns:150px 1fr 70px;gap:10px;align-items:center;font-size:13px}.track{height:8px;background:#eef1f6;border-radius:5px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#6174f5,#7f66ee)}.step{border:1px solid var(--line);border-radius:9px;padding:12px}.step b{color:var(--primary)}.step small{display:block;color:var(--muted);margin-top:4px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px;background:#fff;max-height:630px}table{width:100%;border-collapse:collapse;font-size:13px}th{position:sticky;top:0;background:#f8f9fc;text-align:left;color:#69758a;padding:12px;border-bottom:1px solid var(--line)}td{padding:11px 12px;border-bottom:1px solid #edf0f5;white-space:nowrap}.empty{padding:60px 20px;text-align:center;color:var(--muted)}.form{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin-bottom:16px}.field{display:grid;gap:6px;min-width:220px;flex:1}.field label{font-size:12px;color:var(--muted)}.field select,.field input{border:1px solid var(--line);border-radius:8px;background:#fff;padding:10px}.report-preview{line-height:1.8;white-space:pre-wrap}.download-row{display:flex;gap:10px;margin-top:16px}.alert{border-left:4px solid var(--warn);background:#fffaf0;padding:13px;margin:9px 0;border-radius:7px}.chat-shell{min-height:calc(100vh - 145px);background:#fff;border:1px solid var(--line);border-radius:12px;overflow:hidden}.chat-main{position:relative;padding:20px 28px 125px;min-height:calc(100vh - 145px)}.chat-title{display:flex;align-items:center;padding-bottom:14px;border-bottom:1px solid var(--line)}.chat-title b{font-size:17px}.chat-title .pill{margin-left:auto}.hero{text-align:center;padding:100px 15px 35px}.hero-icon{width:52px;height:52px;margin:auto;border-radius:17px;background:linear-gradient(135deg,#526cf1,#8767ef);color:#fff;display:grid;place-items:center;font-size:24px}.hero h2{font-size:27px;margin:18px 0 8px}.hero p{color:var(--muted)}.chips{display:flex;justify-content:center;gap:9px;flex-wrap:wrap}.chips button{border:1px solid var(--line);background:#fff;border-radius:18px;padding:8px 13px;color:#657189;cursor:pointer}.messages{max-width:900px;margin:22px auto}.msg{display:flex;margin:18px 0}.bubble{max-width:82%;padding:13px 16px;border-radius:12px;line-height:1.72;white-space:pre-wrap}.user{justify-content:flex-end}.user .bubble{background:var(--primary);color:#fff}.bot .bubble{background:#f9faff;border:1px solid var(--line)}.evidence{font-size:12px;color:var(--muted);margin-top:10px}.composer{position:absolute;left:28px;right:28px;bottom:24px;border:1px solid #dbe1ec;background:#fff;border-radius:14px;padding:12px;box-shadow:0 12px 30px #22355d18}.composer textarea{border:0;outline:0;resize:none;width:100%;height:46px}.composer-foot{display:flex;align-items:center}.composer-foot .pill{color:var(--primary);background:var(--soft)}.send{margin-left:auto}.status-text{font-size:12px;color:var(--muted);margin-left:9px}.api-list{display:grid;gap:10px}.api{display:grid;grid-template-columns:65px 210px 1fr;gap:12px;padding:12px;border:1px solid var(--line);border-radius:8px}.method{font-weight:700;color:var(--primary)}@media(max-width:1000px){.cards{grid-template-columns:repeat(2,1fr)}.grid2{grid-template-columns:1fr}.top-status{display:none}}@media(max-width:760px){.side{display:none}.main{margin-left:0}.content{padding:18px}.cards{grid-template-columns:1fr}.chat-main{padding:15px 15px 120px}.composer{left:15px;right:15px}.top-sub{display:none}}
</style></head><body>
<header class="top"><div class="brand"><div class="logo" aria-label="EconAtlas 原版标志"></div>EconAtlas</div><div class="top-sub">全球宏观经济数据要素平台</div><div class="top-status"><span class="pill"><i></i>数据库在线</span><span class="pill"><i></i>API 正常</span><span class="pill" id="ai-status"><i></i>DeepSeek</span></div></header>
<aside class="side"><div class="group">工作台（附加）</div><button class="menu active" data-page="overview"><span>⌂</span>平台总览</button><div class="group">数据服务</div><button class="menu" data-page="indicator-query"><span>⌁</span>指标查询</button><button class="menu" data-page="dictionary"><span>◫</span>指标字典</button><button class="menu" data-page="json-output"><span>{ }</span>JSON输出</button><button class="menu" data-page="assets"><span>▤</span>数据资产目录</button><button class="menu" data-page="api"><span>↔</span>API服务中心</button><div class="group">质量治理</div><button class="menu" data-page="quality"><span>✓</span>数据质量</button><button class="menu" data-page="consistency"><span>≋</span>一致性分析</button><button class="menu" data-page="governance-dashboard"><span>▦</span>治理驾驶舱</button><button class="menu" data-page="lineage"><span>⑂</span>指标血缘</button><button class="menu" data-page="governance-rules"><span>⌘</span>治理规则</button><button class="menu" data-page="risk"><span>△</span>风险预警</button><button class="menu" data-page="asset-rating"><span>◇</span>资产评级</button><button class="menu" data-page="alignment"><span>⊙</span>指标对齐审核</button><div class="group">智能应用</div><button class="menu" data-page="chat"><span>✦</span>智能问答</button><button class="menu" data-page="analysis"><span>⌁</span>智能分析</button><button class="menu" data-page="report"><span>▧</span>智能报告</button><div class="group">运行辅助（附加）</div><button class="menu" data-page="system"><span>◉</span>系统运行</button></aside>
<main class="main"><div class="content" id="content"></div></main>
<script>
const content=document.getElementById('content');let summary=null,metadata=null,catalogData=null,context=null,history=[],lastReport=null,lastQueryRows=[],lastJsonOutput=null,lastAlignmentRows=[];
const fmt=n=>new Intl.NumberFormat('zh-CN').format(Number(n||0));const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');const md=s=>esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\[E(\d+)\]/g,'<span class="pill">[E$1]</span>').replace(/\n/g,'<br>');
async function json(url,opt){const r=await fetch(url,opt);const d=await r.json();if(!r.ok||d.error)throw new Error(d.error||`HTTP ${r.status}`);return d}
async function bootstrap(){[summary,metadata,catalogData]=await Promise.all([json('/dashboard-summary'),json('/metadata'),json('/catalog')]);document.getElementById('ai-status').innerHTML='<i></i>'+(summary.deepseek_configured?'DeepSeek 已配置':'DeepSeek 未配置')}
function head(title,desc,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function overview(){const t=summary.totals||{},f=summary.forecast_scenario||{},valid=t.rows?Math.round(t.valid_rows/t.rows*10000)/100:0,sources=summary.source_counts||[],max=Math.max(...sources.map(x=>x.rows),1);content.innerHTML=head('平台总览',`截至 ${summary.as_of_date} 的已发布数据；预测情景不计入当前资产统计`,'<div class="head-action"><button class="btn" onclick="refreshPage(\'overview\')">刷新数据</button></div>')+`<div class="cards"><div class="card"><label>当前标准观测</label><strong>${fmt(t.rows)}</strong><small>${t.earliest_date||'-'} 至 ${t.latest_date||'-'}</small></div><div class="card"><label>国家与地区</label><strong>${fmt(t.countries)}</strong><small>统一国家编码</small></div><div class="card"><label>标准指标</label><strong>${fmt(t.indicators)}</strong><small>统一指标口径</small></div><div class="card"><label>官方数据来源</label><strong>${fmt(t.sources)}</strong><small>保留完整血缘</small></div><div class="card"><label>有效数据率</label><strong>${valid}%</strong><small>预测记录已隔离 ${fmt(f.rows)} 条</small></div></div><div class="grid2"><section class="panel"><h3>当前数据来源分布</h3><div class="bars">${sources.slice(0,8).map(x=>`<div class="bar-row"><span>${esc(x.source)}</span><div class="track"><div class="fill" style="width:${x.rows/max*100}%"></div></div><b>${fmt(x.rows)}</b></div>`).join('')}</div></section><section class="panel"><h3>数据边界</h3><div class="pipeline"><div class="step"><b>当前已发布数据</b><small>历史值与截至当前日期已发布的派生值</small></div><div class="step"><b>预测情景（独立）</b><small>${fmt(f.rows)} 条，范围 ${f.earliest_date||'-'}—${f.latest_date||'-'}，不进入当前总量</small></div><div class="step"><b>自动质量门禁</b><small>预测语义、完整性与来源可追溯性检查</small></div></div></section></div>`}
async function assets(){content.innerHTML=head('数据资产目录','浏览已治理的当前数据资产（默认排除预测）')+'<div class="panel"><div class="empty">正在读取…</div></div>';const d=await json('/assets?limit=150');content.innerHTML=head('数据资产目录','浏览已治理的当前数据资产（默认排除预测）',`<div class="head-action"><span class="badge">展示 ${d.count} 项</span></div>`)+`<div class="table-wrap"><table><thead><tr><th>国家/地区</th><th>指标</th><th>频率</th><th>来源</th><th>有效/总数</th><th>时间范围</th></tr></thead><tbody>${d.assets.map(x=>`<tr><td>${esc(x.country_name_zh||x.country_code)}</td><td>${esc(x.indicator_name_zh||x.indicator_code)}<br><small>${esc(x.indicator_code)}</small></td><td>${esc(x.frequency)}</td><td>${esc(x.source_organization)}</td><td>${fmt(x.valid_observations)} / ${fmt(x.observations)}</td><td>${esc(x.start_date)} — ${esc(x.end_date)}</td></tr>`).join('')}</tbody></table></div>`}
function dictionary(){const list=catalogData.indicators||[];content.innerHTML=head('指标字典','标准指标编码、名称、单位和当前观测规模')+`<div class="panel"><div class="form"><div class="field"><label>搜索指标</label><input id="indicator-search" placeholder="输入中文名或指标代码" oninput="filterIndicators()"></div></div><div class="table-wrap"><table><thead><tr><th>指标代码</th><th>指标名称</th><th>单位</th><th>当前观测</th></tr></thead><tbody id="indicator-body">${indicatorRows(list)}</tbody></table></div></div>`}function indicatorRows(a){return a.map(x=>`<tr><td>${esc(x.indicator_code)}</td><td>${esc(x.name)}</td><td>${esc(x.unit)}</td><td>${fmt(x.observations)}</td></tr>`).join('')}function filterIndicators(){const q=document.getElementById('indicator-search').value.toLowerCase();document.getElementById('indicator-body').innerHTML=indicatorRows(catalogData.indicators.filter(x=>(x.indicator_code+' '+x.name).toLowerCase().includes(q)))}
function selectorForm(prefix,buttonText,handler){return `<div class="form"><div class="field"><label>国家/地区</label><select id="${prefix}-country">${optionRows(catalogData.countries,'country_code')}</select></div><div class="field"><label>标准指标</label><select id="${prefix}-indicator">${optionRows(catalogData.indicators,'indicator_code')}</select></div><button class="btn primary" onclick="${handler}">${buttonText}</button></div>`}
function queryForm(prefix,buttonText,handler){const frequencies=(metadata.data_asset?.frequencies||[]).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join(''),sources=(metadata.sources||[]).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');return `<div class="form"><div class="field"><label>国家/地区</label><select id="${prefix}-country">${optionRows(catalogData.countries,'country_code')}</select></div><div class="field"><label>标准指标</label><select id="${prefix}-indicator">${optionRows(catalogData.indicators,'indicator_code')}</select></div><div class="field"><label>频率（可选）</label><select id="${prefix}-frequency"><option value="">全部频率</option>${frequencies}</select></div><div class="field"><label>数据来源（可选）</label><select id="${prefix}-source"><option value="">全部来源</option>${sources}</select></div><div class="field"><label>开始日期/年份（可选）</label><input id="${prefix}-start" placeholder="例如 2020 或 2020-01"></div><div class="field"><label>结束日期/年份（可选）</label><input id="${prefix}-end" placeholder="例如 2026 或 2026-06"></div><button class="btn primary" onclick="${handler}">${buttonText}</button></div>`}
function queryParams(prefix){const value=id=>document.getElementById(`${prefix}-${id}`)?.value||'',params=new URLSearchParams({country:value('country'),indicator:value('indicator'),include_forecast:'false'});for(const key of ['start','end','frequency','source'])if(value(key))params.set(key,value(key));return params.toString()}
function setDefaults(prefix){const c=document.getElementById(prefix+'-country'),i=document.getElementById(prefix+'-indicator');if(c&&[...c.options].some(x=>x.value==='CN'))c.value='CN';if(i&&[...i.options].some(x=>x.value==='CPI_YOY_M'))i.value='CPI_YOY_M'}
function indicatorQuery(){content.innerHTML=head('指标查询','按国家、指标、频率、来源和时间范围查询已发布数据，默认不包含预测值')+`<div class="panel">${queryForm('query','查询数据','runIndicatorQuery()')}<div id="query-result" class="empty">请选择查询条件。</div></div>`;setDefaults('query')}
async function runIndicatorQuery(){const box=document.getElementById('query-result');box.className='empty';box.textContent='正在查询…';try{const d=await json(`/series-data?${queryParams('query')}`);lastQueryRows=d.rows||[];box.className='';box.innerHTML=seriesView(lastQueryRows,'指标趋势')+(lastQueryRows.length?'<div class="download-row"><button class="btn" onclick="downloadRowsCsv(lastQueryRows,\'EconAtlas-query.csv\')">下载查询结果 CSV</button></div>':'')+objectTableInner(lastQueryRows)}catch(e){box.textContent=e.message}}
function seriesView(rows,title='趋势图'){if(!rows?.length)return '<div class="empty">当前条件没有已发布数据</div>';const primary=[...new Set(rows.map(x=>x.source_organization))][0],data=rows.filter(x=>x.source_organization===primary).slice(-48),vals=data.map(x=>Number(x.value)),lo=Math.min(...vals),hi=Math.max(...vals),span=hi-lo||1,pts=data.map((x,i)=>`${30+i*700/Math.max(data.length-1,1)},${170-(Number(x.value)-lo)*130/span}`).join(' ');return `<div style="margin:18px 0"><h3>${title} <span class="badge">${esc(primary)}</span></h3><svg viewBox="0 0 760 205" style="width:100%;height:250px;background:#fafbff;border:1px solid var(--line);border-radius:10px"><line x1="30" y1="170" x2="730" y2="170" stroke="#dbe1ec"/><polyline points="${pts}" fill="none" stroke="#5868ef" stroke-width="3"/><text x="30" y="195" fill="#7b879b" font-size="12">${esc(data[0].date)}</text><text x="675" y="195" fill="#7b879b" font-size="12">${esc(data[data.length-1].date)}</text><text x="35" y="20" fill="#7b879b" font-size="12">${hi.toFixed(2)}</text></svg></div>`}
function objectTableInner(rows){if(!rows?.length)return '';const cols=['date','value','unit','frequency','source_organization','observation_type'];return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows.slice(-200).reverse().map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
async function quality(){content.innerHTML=head('数据质量','读取真实质量检查、覆盖率、一致性和异常值报告')+'<div class="empty">正在执行质量结果读取…</div>';const d=await json('/quality-status'),t=summary.totals,rate=t.rows?(t.valid_rows/t.rows*100).toFixed(2):0;content.innerHTML=head('数据质量','读取真实质量检查、覆盖率、一致性和异常值报告')+`<div class="cards"><div class="card"><label>有效观测</label><strong>${fmt(t.valid_rows)}</strong><small>当前数据</small></div><div class="card"><label>完整率</label><strong>${rate}%</strong><small>非空值比例</small></div><div class="card"><label>质量警示</label><strong>${fmt(d.checks_warnings)}</strong><small>${fmt(d.checks_count)} 项检查</small></div><div class="card"><label>一致性警示</label><strong>${fmt(d.consistency_warnings)}</strong><small>${fmt(d.consistency_count)} 组比较</small></div><div class="card"><label>异常观测</label><strong>${fmt(d.outliers_count)}</strong><small>真实扫描结果</small></div></div>${objectTable('质量检查明细',d.checks)}`}
function governanceRules(){const t=summary.totals;content.innerHTML=head('治理规则','展示实际采用的数据标准化与语义隔离规则')+`<div class="grid2"><section class="panel"><h3>正在运行的治理规则</h3><div class="pipeline"><div class="step"><b>统一指标映射</b><small>来源代码映射至标准 indicator_code</small></div><div class="step"><b>频率与单位标准化</b><small>年度、季度、月度与日度口径可识别</small></div><div class="step"><b>数据语义隔离</b><small>historical / derived / forecast 分层；预测不混入当前总览</small></div><div class="step"><b>来源血缘保留</b><small>机构、数据集、原始代码与来源 URL 可追溯</small></div></div></section><section class="panel"><h3>治理后的当前资产</h3><p><b>${fmt(t.rows)}</b> 条观测</p><p><b>${fmt(t.indicators)}</b> 个标准指标</p><p><b>${fmt(t.sources)}</b> 个权威来源</p></section></div>`}
function governanceDashboard(){const t=summary.totals,f=summary.forecast_scenario;content.innerHTML=head('治理驾驶舱','汇总采集、标准化、质量门禁、资产化和服务状态')+`<div class="cards"><div class="card"><label>采集入库</label><strong>${fmt(t.rows)}</strong><small>当前已发布观测</small></div><div class="card"><label>标准化指标</label><strong>${fmt(t.indicators)}</strong></div><div class="card"><label>权威来源</label><strong>${fmt(t.sources)}</strong></div><div class="card"><label>预测隔离</label><strong>${fmt(f.rows)}</strong><small>不混入当前资产</small></div><div class="card"><label>服务状态</label><strong style="color:var(--good)">正常</strong></div></div><div class="panel" style="margin-top:16px"><div class="pipeline"><div class="step"><b>01 多源采集</b><small>官方与权威来源定时更新</small></div><div class="step"><b>02 标准治理</b><small>国家、指标、频率、单位统一</small></div><div class="step"><b>03 质量门禁</b><small>完整性、一致性、异常值检查</small></div><div class="step"><b>04 数据资产化</b><small>目录、评级、血缘与 API 输出</small></div></div></div>`}
async function risk(){content.innerHTML=head('风险预警','基于真实质量、一致性和异常观测报告生成')+'<div class="empty">正在计算风险…</div>';const d=await json('/risk-alerts');content.innerHTML=head('风险预警','基于真实质量、一致性和异常观测报告生成')+`<div class="cards"><div class="card"><label>质量警示项</label><strong>${fmt(d.quality_warnings)}</strong><small>质量门禁报告</small></div><div class="card"><label>多源偏差警示</label><strong>${fmt(d.consistency_warnings)}</strong><small>一致性报告</small></div><div class="card"><label>异常观测</label><strong>${fmt(d.outlier_count)}</strong><small>离群扫描</small></div></div>${objectTable('多源一致性预警',d.alerts)}${objectTable('异常观测明细',d.outliers)}`}
async function consistency(){content.innerHTML=head('一致性分析','识别同一国家、指标和时期的多来源数值偏差')+'<div class="empty">正在读取一致性报告…</div>';const d=await json('/quality-status'),rows=(d.consistency||[]),warnings=rows.filter(x=>String(x.status).toLowerCase()==='warning');content.innerHTML=head('一致性分析','识别同一国家、指标和时期的多来源数值偏差')+`<div class="cards"><div class="card"><label>比较记录</label><strong>${fmt(d.consistency_count)}</strong></div><div class="card"><label>偏差警示</label><strong>${fmt(d.consistency_warnings)}</strong></div><div class="card"><label>当前展示</label><strong>${fmt(warnings.length)}</strong><small>前 200 条范围</small></div></div>${objectTable('多源偏差明细',warnings)}`}
async function lineage(){content.innerHTML=head('指标血缘','追踪来源机构、原始指标代码与标准指标映射')+'<div class="empty">正在读取血缘关系…</div>';const d=await json('/lineage');content.innerHTML=head('指标血缘','追踪来源机构、原始指标代码与标准指标映射',`<div class="head-action"><span class="badge">${fmt(d.count)} 条映射</span></div>`)+objectTable('来源—数据集—原始代码—标准代码',d.mappings)}
async function assetRating(){content.innerHTML=head('资产评级','按完整性、覆盖度、多源、规模和新鲜度计算 S/A/B/C/D 等级')+'<div class="empty">正在计算资产等级…</div>';const d=await json('/asset-ratings'),dist=d.distribution||[];content.innerHTML=head('资产评级',d.method,`<div class="head-action"><span class="badge">${fmt(d.count)} 项资产</span></div>`)+`<div class="cards">${dist.map(x=>`<div class="card"><label>${esc(x.asset_level)} 级资产</label><strong>${fmt(x.count)}</strong></div>`).join('')}</div>${objectTable('资产评级明细',d.assets)}`}
async function alignment(){content.innerHTML=head('指标对齐审核','展示来源指标到标准指标的候选匹配、置信度和复核状态')+'<div class="empty">正在读取对齐候选…</div>';const d=await json('/alignment-candidates');lastAlignmentRows=d.candidates||[];const statuses=[...new Set(lastAlignmentRows.map(x=>x.review_status).filter(Boolean))],levels=[...new Set(lastAlignmentRows.map(x=>x.confidence_level).filter(Boolean))],sources=[...new Set(lastAlignmentRows.map(x=>x.source).filter(Boolean))];content.innerHTML=head('指标对齐审核','保留旧版“系统推荐 + 置信评分 + 人工复核”候选审核表',`<div class="head-action"><span class="badge">${fmt(d.count)} 条候选</span></div>`)+`<div class="cards">${(d.distribution||[]).map(x=>`<div class="card"><label>${esc(x.confidence_level)}</label><strong>${fmt(x.count)}</strong></div>`).join('')}</div><div class="panel" style="margin-top:16px"><div class="form"><div class="field"><label>审核状态</label><select id="align-status" onchange="filterAlignment()"><option value="">全部</option>${statuses.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>置信等级</label><select id="align-level" onchange="filterAlignment()"><option value="">全部</option>${levels.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>数据来源</label><select id="align-source" onchange="filterAlignment()"><option value="">全部</option>${sources.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><button class="btn" onclick="downloadRowsCsv(lastAlignmentRows,'alignment_candidates.csv')">下载候选审核表 CSV</button></div><div id="alignment-table">${objectTableInnerGeneric(lastAlignmentRows)}</div></div>`}
function filterAlignment(){const status=document.getElementById('align-status').value,level=document.getElementById('align-level').value,source=document.getElementById('align-source').value,rows=lastAlignmentRows.filter(x=>(!status||x.review_status===status)&&(!level||x.confidence_level===level)&&(!source||x.source===source));document.getElementById('alignment-table').innerHTML=objectTableInnerGeneric(rows)}
function jsonOutput(){content.innerHTML=head('JSON输出','按比赛要求，以国家、指标、频率、来源和时间范围生成标准化结构化数据')+`<div class="panel">${queryForm('json','生成 JSON','runJsonOutput()')}<div id="json-download"></div><pre id="json-result" style="white-space:pre-wrap;background:#0f172a;color:#dbeafe;padding:18px;border-radius:10px;max-height:620px;overflow:auto">请选择条件并生成 JSON。</pre></div>`;setDefaults('json')}
async function runJsonOutput(){const box=document.getElementById('json-result');box.textContent='正在生成…';try{lastJsonOutput=await json(`/query?${queryParams('json')}`);box.textContent=JSON.stringify(lastJsonOutput,null,2);document.getElementById('json-download').innerHTML='<div class="download-row" style="margin:0 0 14px"><button class="btn" onclick="downloadJsonOutput()">下载 JSON 文件</button></div>'}catch(e){box.textContent=e.message}}
function objectTable(title,rows){if(!rows?.length)return `<div class="panel" style="margin-top:16px"><h3>${title}</h3><div class="empty">当前没有记录</div></div>`;const cols=Object.keys(rows[0]).slice(0,8);return `<div class="panel" style="margin-top:16px"><h3>${title}</h3><div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,100).map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function objectTableInnerGeneric(rows){if(!rows?.length)return '<div class="empty">当前没有记录</div>';const cols=Object.keys(rows[0]).slice(0,10);return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,200).map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function downloadRowsCsv(rows,name){if(!rows?.length)return;const cols=Object.keys(rows[0]),data='\ufeff'+[cols.join(','),...rows.map(r=>cols.map(c=>'"'+String(r[c]??'').replaceAll('"','""')+'"').join(','))].join('\n');downloadBlob(data,'text/csv',name)}
function downloadJsonOutput(){if(lastJsonOutput)downloadBlob(JSON.stringify(lastJsonOutput,null,2),'application/json','EconAtlas-query.json')}
function downloadBlob(data,mime,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:mime}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function optionRows(rows,key){return rows.map(x=>`<option value="${esc(x[key])}">${esc(x.name)}（${esc(x[key])}）</option>`).join('')}
function report(){reportWorkspace(true)}function analysis(){reportWorkspace(false)}
function reportWorkspace(downloads){const title=downloads?'智能报告':'智能分析',desc=downloads?'生成包含趋势图、DeepSeek 分析和治理说明的多格式报告':'对已发布数据进行趋势、统计和 DeepSeek 证据分析';content.innerHTML=head(title,desc)+`<div class="panel">${selectorForm('report',downloads?'生成报告':'开始分析',`generateReport(${downloads})`)}<div id="report-result" class="empty">尚未${downloads?'生成报告':'开始分析'}。系统默认排除预测值。</div></div>`;setDefaults('report')}
async function generateReport(downloads=true){const box=document.getElementById('report-result'),button=box.parentElement.querySelector('.btn.primary');button.disabled=true;box.className='empty';box.textContent='正在检索 EconAtlas，并由 DeepSeek 生成严谨分析…';try{lastReport=await json('/reports/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({country:document.getElementById('report-country').value,indicator:document.getElementById('report-indicator').value})});box.className='';const downloadHtml=downloads?`<div class="download-row"><button class="btn primary" onclick="downloadPdf()">下载 PDF 报告</button><button class="btn" onclick="downloadReport('md')">下载 Markdown</button><button class="btn" onclick="downloadReport('json')">下载 JSON</button><button class="btn" onclick="downloadReport('csv')">下载数据 CSV</button></div>`:'';box.innerHTML=`<h3>${esc(lastReport.country_name)} · ${esc(lastReport.indicator_name)} <span class="badge">${esc(lastReport.analysis_mode)}</span></h3><div class="alert">${esc(lastReport.summary)}</div><div class="cards"><div class="card"><label>时间范围</label><strong style="font-size:18px">${esc(lastReport.stats.start)}—${esc(lastReport.stats.end)}</strong><small>仅已发布数据</small></div><div class="card"><label>最新值</label><strong>${esc(lastReport.stats.latest)}${esc(lastReport.stats.unit)}</strong></div><div class="card"><label>有效观测</label><strong>${fmt(lastReport.stats.count)}</strong></div><div class="card"><label>预测值</label><strong>0</strong><small>已严格排除</small></div></div>${seriesView(lastReport.series,'已发布数据趋势')}<h3>DeepSeek 证据分析</h3><div class="report-preview">${md(lastReport.ai_analysis)}</div>${downloadHtml}`}catch(e){box.textContent=e.message}finally{button.disabled=false}}
function downloadPdf(){if(!lastReport)return;window.open(`/reports/pdf?country=${encodeURIComponent(lastReport.country)}&indicator=${encodeURIComponent(lastReport.indicator)}`,'_blank')}
function downloadReport(type){if(!lastReport)return;let data,mime,name;if(type==='md'){data=lastReport.markdown;mime='text/markdown';name='EconAtlas-report.md'}else if(type==='json'){data=JSON.stringify(lastReport,null,2);mime='application/json';name='EconAtlas-report.json'}else{const rows=lastReport.series,cols=Object.keys(rows[0]);data='\ufeff'+[cols.join(','),...rows.map(r=>cols.map(c=>'"'+String(r[c]??'').replaceAll('"','""')+'"').join(','))].join('\n');mime='text/csv';name='EconAtlas-report-data.csv'}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:mime}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function apiPage(){const endpoints=[['GET','/api','服务说明'],['GET','/health','健康检查'],['GET','/dashboard-summary','当前资产统计'],['GET','/assets','数据资产目录'],['GET','/catalog','指标与国家字典'],['GET','/series-data','已发布时间序列'],['GET','/query','标准 JSON 查询输出'],['POST','/batch_query','批量 JSON 查询'],['GET','/quality-status','质量与一致性结果'],['GET','/lineage','指标血缘映射'],['GET','/alignment-candidates','指标对齐候选'],['GET','/asset-ratings','资产评级'],['GET','/risk-alerts','风险预警'],['POST','/chat','DeepSeek + EconAtlas 问答'],['POST','/reports/generate','智能报告生成'],['GET','/reports/pdf','PDF 报告下载'],['GET','/system-status','系统运行状态']];content.innerHTML=head('API服务中心','比赛要求的结构化 JSON 服务与平台功能接口',`<div class="head-action"><button class="btn" onclick="window.open('/docs','_blank')">打开 API 文档</button></div>`)+`<div class="panel"><div class="api-list">${endpoints.map(x=>`<div class="api"><span class="method">${x[0]}</span><code>${x[1]}</code><span>${x[2]}</span></div>`).join('')}</div></div>`}
async function system(){content.innerHTML=head('系统运行','读取云端服务、数据库与自动化更新的真实状态')+'<div class="empty">正在读取系统状态…</div>';const d=await json('/system-status'),update=d.scheduled_update||{},deepseek=d.deepseek==='configured';content.innerHTML=head('系统运行','读取云端服务、数据库与自动化更新的真实状态')+`<div class="cards"><div class="card"><label>数据库</label><strong style="color:${d.database==='ok'?'var(--good)':'var(--bad)'}">${d.database==='ok'?'在线':'异常'}</strong><small>${fmt(d.database_bytes)} 字节</small></div><div class="card"><label>HTTP API</label><strong style="color:${d.service==='ok'?'var(--good)':'var(--bad)'}">${d.service==='ok'?'正常':'异常'}</strong><small>${esc(d.deployment)}</small></div><div class="card"><label>DeepSeek</label><strong style="color:${deepseek?'var(--good)':'var(--bad)'}">${deepseek?'已配置':'未配置'}</strong><small>实际调用结果以问答请求为准</small></div><div class="card"><label>数据库版本日期</label><strong style="font-size:19px">${esc(d.database_modified_at||'-')}</strong></div><div class="card"><label>统计日期</label><strong style="font-size:19px">${esc(summary.as_of_date)}</strong><small>当前数据默认排除预测</small></div></div>${objectTable('自动更新状态',Object.keys(update).length?[update]:[])}`}
function chat(){const aiReady=summary.deepseek_configured;content.innerHTML=head('智能问答','仅保留问答工作区；普通问题由 DeepSeek 回答，宏观数据问题先检索 EconAtlas')+`<div class="chat-shell"><section class="chat-main"><div class="chat-title"><b>智能问答</b><span class="pill"><i></i>${aiReady?'DeepSeek 已配置':'DeepSeek 未配置'} · 数据检索可用</span></div><div class="hero" id="hero"><div class="hero-icon">✦</div><h2>EconAtlas 智能问答</h2><p>普通问题由 DeepSeek 回答，宏观数据问题自动检索 EconAtlas</p><div class="chips"><button onclick="ask(this.textContent)">你好，你能做什么？</button><button onclick="ask(this.textContent)">解释一下什么是 GDP</button><button onclick="ask(this.textContent)">中国近五年的通胀趋势</button></div></div><div class="messages" id="messages"></div><div class="composer"><textarea id="question" placeholder="直接提问；Enter 发送，Shift+Enter 换行"></textarea><div class="composer-foot"><span class="pill">DeepSeek · EconAtlas 数据增强</span><span class="status-text" id="chat-status"></span><button class="btn primary send" id="send" onclick="submitQuestion()">发送 ➤</button></div></div></section></div>`;document.getElementById('question').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();submitQuestion()}})}
function addMessage(role,text,evidence=[]){document.getElementById('hero').style.display='none';const el=document.createElement('div');el.className='msg '+role;const b=document.createElement('div');b.className='bubble';b.innerHTML=md(text);if(evidence.length){const x=document.createElement('div');x.className='evidence';x.textContent='数据证据：'+evidence.length+' 条 · 来源：'+[...new Set(evidence.map(v=>v.source_organization).filter(Boolean))].join('、');b.appendChild(x)}el.appendChild(b);document.getElementById('messages').appendChild(el);el.scrollIntoView({behavior:'smooth',block:'end'})}
function ask(t){document.getElementById('question').value=t;submitQuestion()}async function submitQuestion(){const q=document.getElementById('question'),send=document.getElementById('send'),status=document.getElementById('chat-status'),text=q.value.trim();if(!text||send.disabled)return;const prior=history.slice(-20);addMessage('user',text);history.push({role:'user',content:text});q.value='';send.disabled=true;status.textContent='DeepSeek 正在理解问题…';try{const d=await json('/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:text,context,history:prior})});context=d.context;addMessage('bot',d.answer,d.evidence||[]);history.push({role:'assistant',content:d.answer})}catch(e){addMessage('bot','暂时无法生成回答：'+e.message)}finally{send.disabled=false;status.textContent=''}}
async function refreshPage(page){summary=null;await bootstrap();loadPage(page)}async function loadPage(page){document.querySelectorAll('.menu').forEach(x=>x.classList.toggle('active',x.dataset.page===page));if(!summary)await bootstrap();const pages={overview,'indicator-query':indicatorQuery,dictionary,'json-output':jsonOutput,assets,api:apiPage,quality,consistency,'governance-dashboard':governanceDashboard,lineage,'governance-rules':governanceRules,risk,'asset-rating':assetRating,alignment,chat,analysis,report,system};await (pages[page]||overview)()}
document.querySelectorAll('.menu').forEach(x=>x.onclick=()=>loadPage(x.dataset.page));loadPage('overview');
</script></body></html>'''
